{"command": "cd /workspace && python3 - <<'PY'
import json

record = {
    "row_id": "C0000-04",
    "source_sku": "SKU-0000-04",
    "source": "marketplace",
    "brand": "Lumen Electronics",
    "model": "pd-100s",
    "category": "charger",
    "pack_size": "1 pcs",
    "title": "Lumen PD100S new edition",
    "attributes": {"power": "100000 mW", "connector": "usb c"},
}
rules = {
    "brand_aliases": {
        "LUMEN": "Lumen", "ORION": "Orion", "HALO": "Halo", "ZEPHYR": "Zephyr",
        "Lumen Electronics": "Lumen", "Orion Electronics": "Orion",
        "Halo Electronics": "Halo", "Zephyr Electronics": "Zephyr",
    },
    "source_priority": {"manufacturer": 0, "distributor": 1, "marketplace": 2},
    "attribute_aliases": {"usb c": "USB-C", "USB-C": "USB-C", "nvme": "NVMe", "NVMe": "NVMe"},
}

def norm_model(m):
    return m.replace(" ", "").replace("-", "").upper()

brand = rules["brand_aliases"].get(record["brand"], record["brand"])
model = norm_model(record["model"])
model = model if model else None
pack = record["pack_size"]

# pack_size integer or "N pcs"
def parse_pack(p):
    if p is None:
        return None
    if isinstance(p, int):
        return p
    s = str(p).strip()
    if s == "":
        return None
    if s.lower().endswith("pcs"):
        return int(s.lower().replace("pcs", "").strip())
    return int(s)

pack_int = parse_pack(pack)

if model is None:
    reason = "missing_model"
elif pack_int is None:
    reason = "missing_pack_size"
else:
    reason = None

res = {
    "source_sku": record["source_sku"],
    "source_row": record["row_id"],
    "source": record["source"],
    "priority": rules["source_priority"][record["source"]],
    "entity_id": None,
    "reason": reason,
}

if reason is None:
    # entity_id
    cat = record["category"]
    base = f"{brand.upper()}:{model}:{cat}:pack{pack_int}"
    if cat == "storage":
        base += ":gb" + str(0)  # no capacity given
    # cable? not here
    res["entity_id"] = base
    res["brand"] = brand
    res["model"] = model
    res["category"] = cat
    res["pack_size"] = pack_int
    attrs = {}
    for k, v in record["attributes"].items():
        if k == "power":
            # mW -> W: value/1000
            num = int(str(v).lower().replace("mw", "").strip())
            attrs["power_w"] = int(num * 0.001)
        elif k == "capacity":
            s = str(v).upper()
            if s.endswith("TB"):
                attrs["capacity_gb"] = int(float(s.replace("TB", "").strip()) * 1000)
            else:
                attrs["capacity_gb"] = int(float(s.replace("GB", "").strip()))
        elif k == "length":
            s = str(v).lower()
            if s.endswith("cm"):
                attrs["length_mm"] = int(float(s.replace("cm", "").strip()) * 10)
            elif s.endswith("mm"):
                attrs["length_mm"] = int(float(s.replace("mm", "").strip()))
            else:
                attrs["length_mm"] = int(float(s.replace("m", "").strip()) * 1000)
        elif k in ("connector", "interface"):
            attrs[k] = rules["attribute_aliases"].get(str(v), v)
        elif k == "color":
            attrs[k] = str(v).lower()
        else:
            attrs[k] = v
    res["attributes"] = attrs

print(json.dumps(res, indent=2))

payload = {"task_id": "normalize-sku-0000-04", "artifact": {"kind": "json", "value": res}}
with open("payload.json", "w") as f:
    json.dump(payload, f)
print("written")
PY"}

